mapper.select:
SELECT

FROM TBL_GUARANTEE_CONTRACTS gc



        AND gc.CONTRACT_NO LIKE CONCAT('%', #{query.contractNo}, '%')


        AND gc.COMPANY_ID = #{query.companyId}


        AND gc.CONTRACT_TYPE = #{query.contractType}


        AND gc.GUARANTEE_TYPE = #{query.guaranteeType}


        AND gc.CONTRACT_STATUS = #{query.contractStatus}


        AND gc.RISK_LEVEL = #{query.riskLevel}


        AND gc.CONTRACT_START_DATE >= #{query.startDate}


        AND gc.CONTRACT_END_DATE <= #{query.endDate}


        AND gc.ORGID = #{query.orgId}


ORDER BY gc.CREATED_TIME DESC

SELECT

FROM TBL_GUARANTEE_CONTRACTS gc

WHERE gc.ID = #{id}

SELECT

FROM TBL_GUARANTEE_CONTRACTS gc

WHERE gc.CONTRACT_STATUS = #{contractStatus}

    AND gc.ORGID = #{orgId}

ORDER BY gc.CREATED_TIME DESC

SELECT

FROM TBL_GUARANTEE_CONTRACTS gc

WHERE gc.CONTRACT_STATUS = 'EFFECTIVE'
AND gc.CONTRACT_END_DATE BETWEEN SYSDATE AND SYSDATE + #{days}

    AND gc.ORGID = #{orgId}

ORDER BY gc.CONTRACT_END_DATE ASC

SELECT COUNT(*)
FROM TBL_GUARANTEE_CONTRACTS
WHERE CONTRACT_NO = #{contractNo}

    AND ID != #{excludeId}

